  aboutTagline: "Connecting travellers with the world from Panama",
  aboutQueEs: "Qu'est-ce que KAVARI ?",
  aboutDesc1: "KAVARI is a smart tourism digital platform that connects travellers with real information, certified guides and destinations around the world. Our mission is to make planning a trip a simple, reliable and exciting experience.",
