  modalGuiasTerminos: "J'accepte les Conditions générales",
  modalGuiasTerminosTexto: "En t'inscrivant, tu acceptes les conditions du programme de guides certifiés de KAVARI et la politique de confidentialité.",
  tutorialSaltar: "Passer le tutoriel",
  tutorialAnterior: "Précédent",
