  paisColombia_guias_0_name: "Andrea León",
  paisColombia_guias_0_description: "Historienne et guide à Bogotá. Spécialiste du centre historique, du Musée de l'Or et de l'architecture coloniale de La Candelaria.",
  paisColombia_guias_1_name: "Mateo Restrepo",
  paisColombia_guias_1_description: "Guide urbain à Medellín. Connaît la Comuna 13, l'art urbain et la transformation sociale de la ville. Expert de la culture paisa.",
  paisColombia_guias_2_name: "Valentina Díaz",
  paisColombia_guias_2_description: "Née à Cartagena, guide certifiée de la ville fortifiée. Propose des visites gastronomiques et des parcours à Getsemaní avec un accent historique.",
  paisColombia_guias_3_name: "Carlos Arango",
  paisColombia_guias_3_description: "Guide d'aventure dans l'Eje Cafetero. Emmène les voyageurs à la vallée de Cocora, dans les plantations de café et sur les itinéraires d'observation du quetzal.",
  paisColombia_guias_4_description: "Biologiste spécialisée en Amazonie. Guide à Leticia pour l'observation des dauphins roses, les communautés autochtones et la randonnée en forêt.",
  paisColombia_guias_5_name: "Felipe Archbold",
  paisColombia_guias_5_description: "Plongeur professionnel et guide à San Andrés. Connaît tous les sites de snorkeling et de plongée de l'archipel, ainsi que la culture raizal.",
  paisColombia_souvenirs_0_nombre: "Artisanats de la Candelaria",
  paisColombia_souvenirs_0_descripcion: "Le quartier le plus traditionnel de Bogotá concentre les boutiques de mochilas wayuu, de céramique de Ráquira et de reproductions d'art précolombien.",
  paisColombia_souvenirs_0_productos_0_nombre: "Mochila Wayuu",
  paisColombia_souvenirs_0_productos_0_descripcion: "Tissé à la main par la communauté wayuu à La Guajira. Chaque mochila présente des motifs uniques représentant la vision du monde de sa créatrice.",
  paisColombia_souvenirs_0_productos_1_nombre: "Céramique de Ráquira",
  paisColombia_souvenirs_0_productos_1_descripcion: "Pièces d'argile peintes à la main, techniques ancestrales du peuple boyacense.",
  paisColombia_souvenirs_0_productos_2_nombre: "Réplique de Figure d'Or",
  paisColombia_souvenirs_0_productos_2_descripcion: "Reproduction de pièces du Musée de l'Or. Représente l'orfèvrerie des cultures quimbaya, muisca et zenú.",
  paisColombia_souvenirs_0_productos_3_nombre: "Sac de Fique",
  paisColombia_souvenirs_0_productos_3_descripcion: "Sac tissé en fibres de fique, matériau naturel de la région andine. Écologique et durable.",
  paisColombia_souvenirs_0_productos_4_nombre: "Peinture de Paysage Colombien",
  paisColombia_souvenirs_0_productos_4_descripcion: "Aquarelles et huiles d'artistes locaux représentant la vallée de Cocora, la Caraïbe et la forêt amazonienne.",
  paisColombia_souvenirs_1_descripcion: "Face à la place de Cartagena, ce portail propose des sombreros vueltiaos, de la joaillerie d'émeraudes et des douceurs typiques de la région caribe.",
  paisColombia_souvenirs_1_productos_0_nombre: "Sombrero Vueltiao",
  paisColombia_souvenirs_1_productos_0_descripcion: "Tissé en caña flecha par des artisans de la région caribe. Symbole national de Colombie. Les meilleurs viennent de Sincelejo.",
  paisColombia_souvenirs_1_productos_1_nombre: "Joaillerie d'Émeraudes",
  paisColombia_souvenirs_1_productos_1_descripcion: "La Colombie est le premier producteur d'émeraudes au monde. Bagues, colliers et boucles d'oreilles avec des pierres de haute qualité.",
  paisColombia_souvenirs_1_productos_2_nombre: "Douceurs de Goyave et Coco",
  paisColombia_souvenirs_1_productos_2_descripcion: "Douceurs typiques cartageneras : cocadas, bocadillo de goyave et panelitas de leche. Emballage artisanal.",
  paisColombia_souvenirs_1_productos_3_nombre: "Éventail de Mola",
  paisColombia_souvenirs_1_productos_3_descripcion: "Éventail avec applications de la technique mola, inspirée de l'art textile guna. Héritage caribéen.",
  paisColombia_souvenirs_1_productos_4_descripcion: "Collier fabriqué avec des graines de tagua et de chachafruto, peintes à la main avec des teintures naturelles.",
  paisColombia_souvenirs_2_descripcion: "Réplique d'un village antioqueño au sommet du Cerro Nutibara. Vente de carrieles, de figurines en bois et d'artisanat typique.",
  paisColombia_souvenirs_2_productos_0_nombre: "Carriel Antioqueño",
  paisColombia_souvenirs_2_productos_0_descripcion: "Sac en cuir typique de l'arriero paisa, fabriqué à Jericó. Résistant et aux motifs de la culture antioqueña.",
  paisColombia_souvenirs_2_productos_1_nombre: "Figura de Bois Sculptée",
  paisColombia_souvenirs_2_productos_1_descripcion: "Figurines de la faune locale (ours aux lunettes, guacamaya, condor) sculptées à la main dans du bois de guayacán.",
  paisColombia_souvenirs_2_productos_2_nombre: "Poupée de Chiffon Paisa",
  paisColombia_souvenirs_2_productos_2_descripcion: "Poupée habillée avec un costume typique antioqueño, représentant la tradition paysanne du département.",
  paisColombia_souvenirs_2_productos_3_nombre: "Casquette Tricotée",
  paisColombia_souvenirs_2_productos_3_descripcion: "Casquettes et chapeaux tricotés en laine de mouton par les communautés autochtones emberá et wayuu.",
  paisColombia_souvenirs_2_productos_4_nombre: "Kit de Café de Spécialité",
  paisColombia_souvenirs_2_productos_4_descripcion: "Kit avec café d'origine (par ex. Huila, Quindío) en graines ou moulu, accompagné d'une tasse artisanale en céramique.",
  paisColombia_aerolineas_0_descripcion: "La compagnie aérienne nationale de Colombie avec le plus grand centre de connectivité du pays. Dessert l'Amérique, l'Europe et les États-Unis.",
  paisColombia_aerolineas_1_descripcion: "Connecte la Colombie à toute l'Amérique du Sud et au monde. L'alliance LATAM propose des vols directs vers Miami, Madrid et Santiago.",
  paisColombia_aerolineas_2_descripcion: "Compagnie aérienne à bas coût pour les vols nationaux. Tarifs ultra compétitifs pour voyager en Colombie.",
  paisColombia_aerolineas_3_descripcion: "Compagnie aérienne à bas coût reliant la Colombie au Panamá, au Mexique, au Pérou et à la Caraïbe. Base à Bogotá et Medellín.",
  paisColombia_aerolineas_4_descripcion: "Compagnie aérienne d'État reliant les villes reculées comme Leticia, Mitú et l'Amazonie. Vols essentiels pour le pays.",
  paisColombia_hospedajes_0_nombre: "Loft historique à La Candelaria",
  paisColombia_hospedajes_0_descripcion: "Loft de style colonial dans le centre historique de Bogotá. Balcon avec vue sur les collines orientales. À proximité des musées et des places.",
  paisColombia_hospedajes_1_nombre: "Appartement moderne à Chapinero",
  paisColombia_hospedajes_1_descripcion: "Appartement moderne dans une zone résidentielle de Bogotá. À proximité de la Zone T et des meilleurs restaurants de la ville.",
  paisColombia_hospedajes_2_nombre: "Villa panoramique à El Poblado",
  paisColombia_hospedajes_2_descripcion: "Villa de luxe dans le quartier le plus exclusif de Medellín. Piscine, terrasse avec vue sur la vallée et jardins tropicaux.",
  paisColombia_hospedajes_3_nombre: "Appartement confortable à Laureles",
  paisColombia_hospedajes_3_descripcion: "Appartement tranquille à Laureles, près de l'Unidad Deportiva et de l'Avenida 70. Idéal pour les longs séjours.",
  paisColombia_hospedajes_4_nombre: "Maison coloniale à Getsemaní",
  paisColombia_hospedajes_4_descripcion: "Maison coloniale restaurée avec piscine et terrasse au cœur du quartier le plus branché de Cartagena. À deux pas de la muraille.",
  paisColombia_hospedajes_5_nombre: "Suite face à la mer à Bocagrande",
  paisColombia_hospedajes_5_descripcion: "Suite face à la mer des Caraïbes, piscine sur le toit et accès direct à la plage. Immeuble avec sécurité privée.",
