  paisGuatemala_descripcion: "Le Guatemala se trouve en Amérique centrale et est reconnu pour sa grande diversité culturelle et naturelle. Il couvre une superficie de 108 889 km², compte environ 18,4 millions d'habitants, sa capitale est la Ville de Guatemala, sa monnaie le quetzal et sa langue officielle l'espagnol.",
