  paisParaguay_gastronomia_platos_9_nota: "Desserts caseros frecuentes",
  paisParaguay_aventura_titulo: "Aventure & Nature en Paraguay",
  paisParaguay_practica_descripcion: "Moneda, transporte, climat, visados et conectividad pour planificar ton voyage à Paraguay.",
  paisHonduras_nombre: "Honduras",
  paisHonduras_subtitulo: "Terre d'îles",
  paisHonduras_tagline: "Terre d'îles, de culture maya et de plages caraïbes",
  paisHonduras_descripcion: "Le Honduras se trouve au cœur de l'Amérique centrale et se distingue par sa richesse naturelle, ses ruines mayas et ses plages caraïbes. Sa capitale est Tegucigalpa, sa monnaie le lempira et sa langue officielle l'espagnol.",
  paisHonduras_moneda: "Lempira (HNL)",
  paisHonduras_capital: "Tegucigalpa",
