  // Quick facts
  paisNicaragua_quickFacts_0_titulo: "Paysage volcanique",
  paisNicaragua_quickFacts_0_texto: "Le Nicaragua possède l'une des plus grandes concentrations de volcans d'Amérique centrale, notamment le Volcán Concepción sur l'île d'Ometepe et le Volcán Masaya dont le cratère est accessible.",
  paisNicaragua_quickFacts_1_titulo: "Grands lacs",
  paisNicaragua_quickFacts_1_texto: "Le lac de Nicaragua (8 264 km²) est le plus grand lac d'Amérique centrale et abrite des requins d'eau douce. Le lac de Managua complète le Relief lacustre du pays.",
  paisNicaragua_quickFacts_2_titulo: "Double côte",
  paisNicaragua_quickFacts_2_texto: "Le Nicaragua a une côte sur le Pacifique (San Juan del Sur) et sur la mer des Caraïbes (Îles du Maïs, Corn Islands), avec des paysages, des plages et des cultures très différentes (créole versus autochtone).",
  paisNicaragua_quickFacts_3_titulo: "Tradition vivante",
  paisNicaragua_quickFacts_3_texto: "La musique (marimba, son nica), les fêtes patronales et la gastronomie (gallo pinto, nacatamales) sont au cœur de la vie quotidienne nicaraguayenne.",

  // Destinos
  paisNicaragua_destinos_granada_nombre: "Granada",
  paisNicaragua_destinos_granada_tag: "Histoire · Coloniale · Fondée en 1524",
  paisNicaragua_destinos_granada_descripcion: "Ville coloniale bien conservée, célèbre pour son architecture et ses places. Fondée en 1524. L'une des plus anciennes villes des Amériques.",
  paisNicaragua_destinos_granada_detalle: "Cathédrale de Granada. Rue La Calzada. Église de La Merced (vue panoramique). Isletas de Granada (365 îlots sur le lac de Nicaragua). Forteresse La Polvora. Malecón.",
  paisNicaragua_destinos_granada_consejo: "Parcourir le centre à pied, avec des chaussures confortables",

  paisNicaragua_destinos_sanjuan_nombre: "San Juan del Sur",
  paisNicaragua_destinos_sanjuan_tag: "Plage · Surf · Pacifique",
  paisNicaragua_destinos_sanjuan_descripcion: "Village côtier de plage sur le Pacifique nicaraguayen. Très fréquenté pour le tourisme de soleil, de mer et de surf. Couchers de soleil spectaculaires.",
  paisNicaragua_destinos_sanjuan_detalle: "Plage de San Juan del Sur (principale). Christ de la Miséricorde (vues panoramiques). Surf à Maderas, Hermosa, Majagual. Balade en bateau. Pêche sportive.",
  paisNicaragua_destinos_sanjuan_consejo: "Idéal pour la détente et les sports",

  paisNicaragua_destinos_ometepe_nombre: "Île d'Ometepe",
  paisNicaragua_destinos_ometepe_tag: "Volcan · Lac · Aventure",
  paisNicaragua_destinos_ometepe_descripcion: "Île volcanique dans le lac de Nicaragua, formée par deux volcans : Concepción (actif) et Maderas. Paradis naturel unique.",
  paisNicaragua_destinos_ometepe_detalle: "Volcán Concepción (1 610 m, actif, randonnée exigeante). Volcán Maderas (1 394 m, inactif, lagune dans le cratère). Ojo de Agua (piscines naturelles). Pétroglyphes. Plage Santo Domingo.",
  paisNicaragua_destinos_ometepe_consejo: "Prendre des vêtements chauds et de l'eau pour la randonnée",

  paisNicaragua_destinos_managua_nombre: "Managua",
  paisNicaragua_destinos_managua_tag: "Urbain · Capitale",
  paisNicaragua_destinos_managua_descripcion: "Capitale à la vie moderne et riche d'histoire. Centre politique et culturel. Reconstruite après le séisme de 1972.",
  paisNicaragua_destinos_managua_detalle: "Vieille cathédrale de Managua (ruines du séisme). Nouvelle cathédrale. Palais national de la culture. Lac de Managua. Port Salvador Allende (malecón). Ancienne place de la Révolution.",
  paisNicaragua_destinos_managua_consejo: "Parcourir le centre historique et le malecón",

  paisNicaragua_destinos_masaya_nombre: "Volcán Masaya",
  paisNicaragua_destinos_masaya_tag: "Volcan · Parcs nationaux",
  paisNicaragua_destinos_masaya_descripcion: "Parc national du Volcán Masaya. Cratère accessible en voiture jusqu'au bord. On peut y voir de la lave et du soufre.",
  paisNicaragua_destinos_masaya_detalle: "Santiago (cratère principal, émet du gaz et de la lave). Mirador. Centre d'interprétation. Tunnel de lave (grottes volcaniques). Visite nocturne (oiseaux nocturnes).",
  paisNicaragua_destinos_masaya_consejo: "Porter un masque contre le soufre",

  paisNicaragua_destinos_leon_nombre: "León",
  paisNicaragua_destinos_leon_tag: "Histoire · Coloniale · Université",
  paisNicaragua_destinos_leon_descripcion: "Deuxième ville la plus importante du Nicaragua. Centre historique colonial. Université la plus ancienne d'Amérique centrale (1813).",
  paisNicaragua_destinos_leon_detalle: "Cathédrale de León (patrimoine UNESCO, la plus grande d'Amérique centrale, tombes de poètes). Musée d'art Fondation Ortiz-Gurdián. Ruines de León Viejo (patrimoine UNESCO).",
  paisNicaragua_destinos_leon_consejo: "Monter sur le toit de la cathédrale pour la vue",

  paisNicaragua_destinos_islasmaiz_nombre: "Îles du Maïs",
  paisNicaragua_destinos_islasmaiz_tag: "Caraïbes · Snorkeling · Plage",
  paisNicaragua_destinos_islasmaiz_descripcion: "Archipel caraïbe dans la mer des Caraïbes. Eaux turquoises, sable blanc et récifs coralliens.",
  paisNicaragua_destinos_islasmaiz_detalle: "Grande Île du Maïs (développement touristique). Petite Île du Maïs (vierge, communauté autochtone). Plongée sous-marine et snorkeling. Tortues marinas. Poisson frit et homard.",
  paisNicaragua_destinos_islasmaiz_consejo: "Réserver à l'avance, vol depuis Managua",

  paisNicaragua_destinos_rivas_nombre: "Rivas",
  paisNicaragua_destinos_rivas_tag: "Nature · Lacs · Volcans",
  paisNicaragua_destinos_rivas_descripcion: "Région de lacs et de volcans dans le sud du Nicaragua. excellente base pour explorer l'île d'Ometepe et San Juan du Sur.",
  paisNicaragua_destinos_rivas_detalle: "Foire agricole. Église de Rivas. Plages et nature à proximité. Accès à Ometepe. Très adapté pour le tourisme rural.",
  paisNicaragua_destinos_rivas_consejo: "Excellente base pour explorer la région du sud",

  // Cultura
  paisNicaragua_cultura_titulo: "Culture nicaraguayenne",
  paisNicaragua_cultura_descripcion: "La culture nicaraguayenne mêle influences autochtones (chorotega, nahuatl), africaines (créole sur la côte caraïbe) et européennes, avec une forte présence dans la musique, les fêtes et la gastronomie.",
