  paisNicaragua_cultura_items_marimba_descripcion: "Instrument traditionnel très important au Nicaragua. Similaire à la marimba guatémaltèque mais avec son propre style.",
  paisNicaragua_cultura_items_marimba_detalle: "Utilisée lors des fêtes patronales. Le son nica est un genre traditionnel. La marimba est l'instrument national du Nicaragua.",

  paisNicaragua_cultura_items_gallopinto_nombre: "Gallo pinto",
  paisNicaragua_cultura_items_gallopinto_tag: "Gastronomie",
  paisNicaragua_cultura_items_gallopinto_descripcion: "Plat typique très populaire : riz et haricots rouges ou noirs mélangés et frits ensemble. Se mange au petit déjeuner, au déjeuner ou au dîner.",
