  paisNicaragua_cultura_items_fiestas_nombre: "Fête de Notre-Dame de l'Assomption",
  paisNicaragua_cultura_items_fiestas_tag: "Festivité · León",
  paisNicaragua_cultura_items_fiestas_descripcion: "Célébration très populaire à León en décembre. Fête de la Vierge Marie avec processions, musique, danse et feux d'artifice.",
  paisNicaragua_cultura_items_fiestas_detalle: "La Gritería est une tradition où les gens crient « Qui cause tant de joie ? » et distribuent des cadeaux.",

  paisNicaragua_cultura_items_rubendario_nombre: "Rubén Darío",
  paisNicaragua_cultura_items_rubendario_tag: "Littérature · Poésie",
