  paisNicaragua_cultura_items_rubendario_detalle: "Né à Metapa en 1867. Auteur de « Azul » et « Cantos de vida y esperanza ». Sa tombe se trouve dans la cathédrale de León.",

  paisNicaragua_cultura_darkBand_titulo: "Terre de lacs et de volcans",
  paisNicaragua_cultura_darkBand_texto: "Le Nicaragua possède le plus grand lac d'Amérique centrale (lac de Nicaragua, 8 264 km²) et l'une des plus grandes concentrations de volcans de la région. Le pays est le berceau de Rubén Darío, le poète le plus influent de la langue espagnole.",
