  paisNicaragua_practica_itinerario_4_texto: "Cathédrale, Musée Ortiz-Gurdián, León Viejo.",
  paisNicaragua_practica_itinerario_5_titulo: "Retour",
  paisNicaragua_practica_itinerario_5_texto: "Vol depuis Managua.",

  paisNicaragua_practica_temporadas_0_nombre: "Haute saison (saison sèche)",
