  // Guías
  paisNicaragua_guias_0_name: "María José Romero",
  paisNicaragua_guias_0_description: "Guide à Granada. Spécialiste de la ville coloniale, des isletas du lac de Nicaragua et de l'histoire de la ville. Parle nahuatl et anglais.",
  paisNicaragua_guias_1_name: "Javier Morales",
  paisNicaragua_guias_1_description: "Guide à San Juan del Sur. Expert en surf, plages et couchers de soleil. Propose des cours de surf et des promenades en bateau.",
  paisNicaragua_guias_2_name: "Laura Gutiérrez",
  paisNicaragua_guias_2_description: "Guide à Ometepe. Spécialiste des volcans Concepción et Maderas, des pétroglyphes et de la nature de l'île. Parle français et anglais.",
  paisNicaragua_guias_3_name: "Carlos Espinoza",
  paisNicaragua_guias_3_description: "Guide à León. Connaît la cathédrale, le musée Ortiz-Gurdián et l'histoire de la ville. Parle allemand et anglais.",
  paisNicaragua_guias_4_name: "Ana Sandoval",
  paisNicaragua_guias_4_description: "Guide aux Îles du Maïs. Spécialiste du snorkeling, des récifs coralliens et de la culture créole des îles.",
  paisNicaragua_guias_5_name: "Roberto Martínez",
  paisNicaragua_guias_5_description: "Guide à Masaya. Expert du Volcán Masaya, du tunnel de lave et de la géologie de la région. Parle portugais et anglais.",

