  paisNicaragua_souvenirs_1_productos_2_descripcion: "Figurine de tortue marine sculptée en bois, symbole de la faune du Pacifique nicaraguayen.",
  paisNicaragua_souvenirs_1_productos_3_nombre: "T-shirt de surf",
  paisNicaragua_souvenirs_1_productos_3_descripcion: "T-shirt avec des motifs de surf et de plages de San Juan del Sur. Idéal pour les amoureux de la mer.",
