  paisNicaragua_souvenirs_1_productos_4_descripcion: "Porte-clés, Aimants et souvenirs de San Juan del Sur avec le Christ de la Miséricorde et les plages.",

  paisNicaragua_souvenirs_2_nombre: "Marché d'artisanat - Masaya",
  paisNicaragua_souvenirs_2_descripcion: "Marché d'artisanat dans la ville des volcans. Produits en cuir, bois et artisanat de la région.",
  paisNicaragua_souvenirs_2_productos_0_nombre: "Sac en cuir de capybara",
  paisNicaragua_souvenirs_2_productos_0_descripcion: "Sac en cuir de capybara, résistant et léger. Fait par des artisans de la région.",
  paisNicaragua_souvenirs_2_productos_1_nombre: "Figurine de jaguar en bois",
  paisNicaragua_souvenirs_2_productos_1_descripcion: "Figurine de jaguar sculptée en bois, symbole de la faune de la forêt nicaraguayenne.",
  paisNicaragua_souvenirs_2_productos_2_nombre: "Bracelet en graines de la forêt",
  paisNicaragua_souvenirs_2_productos_2_descripcion: "Bracelet en graines de la flore sylvestre, tissé par des artisans locaux. Naturel et coloré.",
  paisNicaragua_souvenirs_2_productos_3_nombre: "Masque de danse des Diablitos",
  paisNicaragua_souvenirs_2_productos_3_descripcion: "Masque en bois peint à la main, représentant la danse des Diablitos de la culture autochtone.",
  paisNicaragua_souvenirs_2_productos_4_nombre: "Peinture de paysage nicaraguayen",
  paisNicaragua_souvenirs_2_productos_4_descripcion: "Huiles et acryliques d'artistes locaux représentant les volcans, les lacs et les paysages du Nicaragua.",

